//--------------------------------------------------------------------------//
void dei_rs_door_open(void)
{
  if(dei_feature_get(DEI_FEAT_TAKEOVER) == DEI_TAKEOVER_DISABLE_W_DOOR_OPEN)
	{
		if(get_gearbox_type() == GEARBOX_MANUAL)
		{
			if(get_rs_mts_progress())
				return;
			
			dei_rs_takeover_without_key = TRUE;
			dei_rs_evt_signal( DEI_RS_EVT_BRAKE ) ; 
		}
		else //auto transmission
		{
			if(door_open_allow_once)
				door_open_allow_once = 0;
			else
			{
				dei_rs_takeover_without_key = TRUE;
				dei_rs_evt_signal( DEI_RS_EVT_BRAKE ) ; 
			}
		}
	}
}

//--------------------------------------------------------------------------//
void dei_rs_unlock_cmd(void)
{
  if(dei_feature_get(DEI_FEAT_TAKEOVER) == DEI_TAKEOVER_DISABLE_W_UNLOCK_CMD)
	{
		dei_rs_takeover_without_key = TRUE;
    dei_rs_evt_signal( DEI_RS_EVT_BRAKE ) ; 
	}
}

